 "content": "def transform(grid):
    # The most frequent color is the background. Each contiguous horizontal
    # segment of another color is one item; pack items by descending color.
    frequencies = {}
    for row in grid:
        for color in row:
            frequencies[color] = frequencies.get(color, 0) + 1
    background = max(frequencies, key=frequencies.get)

    counts = {}
    for row in grid:
        i = 0
        while i < len(row):
            color = row[i]
            if color == background:
                i += 1
                continue
            counts[color] = counts.get(color, 0) + 1
            while i < len(row) and row[i] == color:
                i += 1

    items = []
    for color in sorted(counts, reverse=True):
        items.extend([color] * counts[color])

    # Results are displayed in rows of three, padding the last row with 0.
    return [items[i:i + 3] + [0] * max(0, 3 - len(items[i:i + 3]))
            for i in range(0, len(items), 3)]


